def overlap_minutes(meetings: list[list[int]], k: int) -> int:
    if k > len(meetings):
        return 0

    deltas: dict[int, int] = {}
    for start, end in meetings:
        if start < end:
            deltas[start] = deltas.get(start, 0) + 1
            deltas[end] = deltas.get(end, 0) - 1

    active = 0
    total = 0
    prev_t = 0
    for t, delta in sorted(deltas.items()):
        if active >= k:
            total += t - prev_t
        active += delta
        prev_t = t

    return total
